"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[4979],{74979:e=>{e.exports=JSON.parse('{"slug":"deficit-byudzheta-2026-7-trln-zaimy","locale":"ru","title":"Минфин: дефицит бюджета в 2026 году вырастет до 7,3 трлн рублей, почти в 2 раза больше плана","description":"Дефицит бюджета 2026 года по оценке Минфина 7,3 трлн рублей, 3,2% ВВП. Откуда разрыв, сколько займёт государство и как это влияет на вклады и кредиты.","blocks":[{"id":"b001","kind":"paragraph","text":"Минфин оценивает дефицит федерального бюджета в 2026 году в 7,3 трлн рублей, или 3,2% ВВП. По закону он должен был составить 3,8 трлн, 1,6% ВВП, в 2025 году был 5,7 трлн. Расходы в 2026 году выйдут на 4,5 трлн рублей выше плана, до 48,6 трлн. Доходы окажутся примерно на 1 трлн выше: ненефтегазовые принесут на 2,3 трлн больше, нефтегазовые на 1,3 трлн меньше, 7,6 трлн рублей. Разница в 3,5 трлн и добавилась к плановым 3,8 трлн."},{"id":"b002","kind":"paragraph","text":"Какие расходы выросли, Минфин не расписывает, данные об исполнении расходов на оборону засекречены с 2022 года. В документах к бюджету на оборону в 2026 году заложено 12,1 трлн рублей, на 2027 год 17,1 трлн. Неофициальная оценка расходов этого года около 17 трлн к концу года. Если она верна, на оборону уйдёт примерно на 5 трлн больше плана. Это больше всего перерасхода бюджета: тогда на остальные статьи останется меньше, чем по плану. За январь–июль 2026 года расходы выросли на 14,5% к прошлому году, доходы на 8,8%. Минфин тогда объяснял разрыв авансами по контрактам."},{"id":"b003","kind":"paragraph","text":"Большую часть разрыва государство займёт: чистые заимствования вырастут до 5 трлн рублей вместо 4,2 трлн по программе. Ещё 459 млрд рублей Минфин возьмёт из Фонда национального благосостояния. Вместе это около 5,5 трлн из 7,3 трлн. Чем закроют остальное, в материалах Минфина не сказано. На IV квартал Минфин запланировал продать облигаций федерального займа, ОФЗ, на 2,45 трлн рублей. Это на 63% больше плана II и III кварталов. Госдолг к концу года вырастет до 46,1 трлн рублей, 19,9% ВВП."},{"id":"b004","kind":"paragraph","text":"В городе с одним банком появляется заёмщик, которому нужна очень большая сумма. Денег в банке не прибавилось, поэтому банк поднимает ставку, и кредит дорожает для всех. На долговом рынке такой заёмщик государство. Это называют эффектом вытеснения: займы государства забирают деньги, которые могли бы достаться бизнесу и людям, и поднимают их цену. 23 сентября 2026 года Минфин продал 12-летние ОФЗ под 16,44% годовых при ключевой ставке Банка России 14%. В такую доходность покупатели закладывают и то, что инфляция и ставки надолго останутся высокими."},{"id":"b005","kind":"paragraph","text":"Людей это касается через ставки. Пока государство занимает много и дорого, банкам выгодно покупать ОФЗ, и за вклады они готовы платить больше. Кредиты по той же причине дешевеют медленнее. Расходы сверх доходов добавляют в экономику спрос, а он толкает цены вверх. Банк России учитывает бюджет, когда решает, что делать со ставкой. Следующее решение он примет 23 октября."},{"id":"b006","kind":"paragraph","text":"Длинный вклад закрепит за вкладчиком нынешнюю ставку, хотя при ускорении инфляции часть дохода съест рост цен. На коротком вкладе деньги свободны, зато при снижении ставок банки быстро урежут проценты. Кредит сейчас дорогой. Ждать дешёвого тоже риск: пока бюджет занимает 2,45 трлн рублей за квартал, снижения ставок никто не обещает."},{"id":"b007","kind":"heading","text":"Какой дефицит бюджета России в 2026 году?"},{"id":"b008","kind":"paragraph","text":"Минфин оценивает его в 7,3 трлн рублей, или 3,2% ВВП. По закону о бюджете дефицит должен был составить 3,8 трлн рублей, 1,6% ВВП. В 2025 году он был 5,7 трлн рублей."},{"id":"b009","kind":"heading","text":"Как государство покрывает дефицит бюджета?"},{"id":"b010","kind":"paragraph","text":"В основном займами: чистые заимствования через облигации федерального займа в 2026 году вырастут до 5 трлн рублей, на IV квартал запланировано разместить ОФЗ на 2,45 трлн. Ещё 459 млрд рублей Минфин возьмёт из Фонда национального благосостояния."},{"id":"b011","kind":"heading","text":"Как дефицит бюджета влияет на ставки по вкладам и кредитам?"},{"id":"b012","kind":"paragraph","text":"Когда государство много занимает, деньги дорожают для всех остальных. 23 сентября 2026 года Минфин продал 12-летние ОФЗ под 16,44% годовых при ключевой ставке 14%. Пока банки могут вкладывать в ОФЗ под такую доходность, вклады остаются доходными, а кредиты дешевеют медленно."}],"sources":[{"label":"Минфин повысил оценку дефицита бюджета РФ в 26г до 3,2% ВВП, потратит часть ФНБ и нарастит займы","url":"https://ru.themoscowtimes.com/2026/09/29/eksklyuziv-minfin-povysil-otsenku-defitsita-byudzheta-rf-v-26g-do-32-vvp-potratit-chast-fnb-i-narastit-zaymy-a207226"},{"label":"Дефицит российского бюджета вырос до 6,455 триллиона рублей","url":"https://www.profinance.ru/news2/2026/08/11/cjyj-defitsit-rossijskogo-byudzheta-vyros-do-6455-trilliona-rublej.html"},{"label":"РФ увеличит военные расходы в 27г на 27% от плана","url":"https://ru.themoscowtimes.com/2026/09/28/eksklyuziv-rf-uvelichit-voennye-raskhody-v-27g-na-27-ot-plana-a207209"},{"label":"Военные расходы России в этом году вырастут почти до 17 трлн рублей, на 40% больше плана","url":"https://thebell.io/voennye-raskhody-rossii-v-etom-godu-vyrastut-pochti-do-17-trln-rubley-na-40-bolshe-plana"},{"label":"Минфин планирует привлечь в IV квартале от размещения ОФЗ 2,45 трлн рублей","url":"https://www.interfax.ru/russia/1119745"},{"label":"Минфин РФ разместил ОФЗ ПД-26253 на 15,3 млрд р под 16,44%","url":"https://ru.themoscowtimes.com/2026/09/23/minfin-rf-razmestil-ofz-pd-26253-na-153-mlrd-r-pod-1644-pri-sprose-665-mlrd-r-a206786"},{"label":"Банк России сохранил ключевую ставку на уровне 14%","url":"https://www.cbr.ru/press/keypr/"}],"sourceBodySha256":"0318e1238e0b1b917560ee37a35c2d4c75abd5d23ee16e401de880eeb401e7a6"}')}}]);